; late.asm -- chapter 17: the interrupts off across the frame's signal
; generated by gen17.py
        INCLUDE "msx.inc"
        OUTPUT "late.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
ticks   EQU RESULTS             ; interrupts taken
; Three times the interrupts are switched off just after a frame's interrupt
; and on again later: past the next signal, past two more, and past the next
; with the status read before EI.
init:   di
        ld sp, SYS_AREA
        xor a
        ld (ticks), a
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        in a, (VDP_CTRL)        ; no signal left over from before
        ei
        halt                    ; a frame's interrupt
        di
        ld de, 3600
        call wait               ; past the next signal
l1:     ei
        nop
        nop
        halt                    ; and the next frame's interrupt
        di
        ld de, 6000
        call wait               ; past two more
l2:     ei
        nop
        nop
        halt
        di
        ld de, 3600
        call wait               ; past the next, and then
        in a, (VDP_CTRL)        ; the status read
l3:     ei
        nop
        nop
        halt
        di
stop:   jr stop

; isr: counts the interrupts taken
isr:    push af
        in a, (VDP_CTRL)        ; the status: the VDP takes its signal down
        ld a, (ticks)
        inc a
        ld (ticks), a
        pop af
        ei
        ret

; wait: DE turns of chapter 14's loop, 30 T-states each. Uses A, DE.
wait:   dec de
        ld a, d
        or e
        jr nz, wait
        ret
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
